// Framework for preparing interview questions
record InterviewQuestion(
    String category,
    String question,
    String whyItWorks
) {}

class QuestionPrep {
    List<InterviewQuestion> prepareQuestions() {
        return List.of(
            // Team and role structure
            new InterviewQuestion(
                "team",
                "What does the team structure look like? How many developers will I work with?",
                "Shows you care about collaboration and support"
            ),

            // Technical details
            new InterviewQuestion(
                "tech",
                "What technologies and frameworks does the team primarily use day-to-day?",
                "Demonstrates technical curiosity beyond the job description"
            ),

            // Growth and learning
            new InterviewQuestion(
                "learning",
                "What does the onboarding process look like for new Java developers?",
                "Shows you're thinking about how to ramp up effectively"
            ),

            // Current challenges
            new InterviewQuestion(
                "challenges",
                "What are the biggest technical challenges the team is facing right now?",
                "Signals you want to understand real problems you'll solve"
            ),

            // Personal experience
            new InterviewQuestion(
                "personal",
                "What do you find most rewarding about working here?",
                "Builds rapport and gets authentic insider perspective"
            )
        );
    }
}
