// Structure: Finding + Connection to your style

record CultureResearch(
    String source,           // Where you found it
    String observation,      // What you learned
    String connectionToYou   // How it aligns with you
) {}

var examples = List.of(
    new CultureResearch(
        "Engineering blog post on testing",
        "You require 80% code coverage and practice TDD for critical services",
        "I wrote unit tests for my Spring Boot project and saw how it caught bugs early—I want to work somewhere that values this discipline"
    ),
    new CultureResearch(
        "GitHub repository for open-source library",
        "I noticed detailed PR reviews with constructive feedback and clear guidelines",
        "I learn best through code review feedback, so seeing your thorough review culture tells me I'll grow quickly here"
    ),
    new CultureResearch(
        "Tech talk by your lead architect",
        "You migrated from monolith to microservices and documented the tradeoffs",
        "I built a microservices project for my capstone and faced similar challenges—I want to learn how to handle this at production scale"
    )
);

// Deliver in interview format
String craftAnswer(CultureResearch research) {
    return String.format(
        "I came across your %s where I learned %s. %s",
        research.source, research.observation, research.connectionToYou
    );
}
